//! `tipb.ScalarFuncSig` as Go TiDB v8.5.8 sees it: the values and names of the Go module
//! `github.com/pingcap/tipb` at the revision in TiDB's go.mod (generated by
//! `tools/expr-gen/gen_tipb_sigs.py`). The Rust `tipb` crate is a newer revision with more
//! values and renames the variants (`LTJson` is `LtJson`), so the push-down tables, the
//! warnings and the blacklist (which match `ScalarFuncSig.String()`) use these instead; the
//! Rust enum is only used to build `tipb::Expr` (spec §3.1).

#[path = "tipb_sig_gen.rs"]
mod tipb_sig_gen;

pub use tipb_sig_gen::*;

/// `ScalarFuncSig.String()`: `proto.EnumName(ScalarFuncSig_name, int32(x))`, the name of a
/// known value, else the number.
// go-dep: github.com/pingcap/tipb/go-tipb@v0.0.0-20260605083900-f9f651ef5fbc.ScalarFuncSig.String L1
pub fn scalar_func_sig_string(x: i32) -> String {
    match tipb_sig_gen::NAMES.binary_search_by_key(&x, |&(v, _)| v) {
        Ok(i) => tipb_sig_gen::NAMES[i].1.to_owned(),
        Err(_) => x.to_string(),
    }
}
